import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.Ddyno5UB.js";const d=JSON.parse('{"title":"OpenSSL Mastery","description":"","frontmatter":{},"headers":[],"relativePath":"tips/1-openssl.md","filePath":"tips/1-openssl.md"}'),n={name:"tips/1-openssl.md"};function h(l,s,p,r,k,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="openssl-mastery" tabindex="-1">OpenSSL Mastery <a class="header-anchor" href="#openssl-mastery" aria-label="Permalink to &quot;OpenSSL Mastery&quot;">​</a></h1><p>OpenSSL is the Swiss Army knife of cryptography. While it is incredibly powerful, its command-line arguments are notoriously difficult to memorize. This guide serves as a definitive reference for the most common (and most frustrating) OpenSSL tasks.</p><h2 id="_1-generating-keys-and-csrs" tabindex="-1">1. Generating Keys and CSRs <a class="header-anchor" href="#_1-generating-keys-and-csrs" aria-label="Permalink to &quot;1. Generating Keys and CSRs&quot;">​</a></h2><p>Before you can get an SSL certificate from a Certificate Authority (like Verisign, GoDaddy, or an internal corporate CA), you must generate a <strong>Private Key</strong> and a <strong>Certificate Signing Request (CSR)</strong>.</p><h3 id="generate-a-private-key-rsa-2048-bit" tabindex="-1">Generate a Private Key (RSA 2048-bit) <a class="header-anchor" href="#generate-a-private-key-rsa-2048-bit" aria-label="Permalink to &quot;Generate a Private Key (RSA 2048-bit)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genrsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2048</span></span></code></pre></div><p><em>(Keep this file absolutely secret. Do not share it with anyone, not even the Certificate Authority).</em></p><h3 id="generate-a-csr-interactive" tabindex="-1">Generate a CSR (Interactive) <a class="header-anchor" href="#generate-a-csr-interactive" aria-label="Permalink to &quot;Generate a CSR (Interactive)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> request.csr</span></span></code></pre></div><p>You will be prompted to enter your Country, State, Organization, and Common Name (the domain name, e.g., <code>www.example.com</code>).</p><h3 id="generate-a-csr-with-sans-subject-alternative-names" tabindex="-1">Generate a CSR with SANs (Subject Alternative Names) <a class="header-anchor" href="#generate-a-csr-with-sans-subject-alternative-names" aria-label="Permalink to &quot;Generate a CSR with SANs (Subject Alternative Names)&quot;">​</a></h3><p>Modern browsers (like Chrome) strictly require SANs; they no longer trust the Common Name field alone. To add SANs without creating a complex config file, use this one-liner:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> request.csr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -subj</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/C=US/ST=CA/O=MyCompany/CN=www.example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -addext</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;subjectAltName=DNS:www.example.com,DNS:example.com,IP:10.0.0.1&quot;</span></span></code></pre></div><hr><h2 id="_2-viewing-verifying-certificates" tabindex="-1">2. Viewing &amp; Verifying Certificates <a class="header-anchor" href="#_2-viewing-verifying-certificates" aria-label="Permalink to &quot;2. Viewing &amp; Verifying Certificates&quot;">​</a></h2><p>When someone hands you a <code>.crt</code>, <code>.csr</code>, or <code>.key</code> file, it is usually base64-encoded (PEM format). You cannot read it directly. You must use OpenSSL to decode and display the human-readable text.</p><h3 id="view-a-certificate-crt-pem" tabindex="-1">View a Certificate (<code>.crt</code> / <code>.pem</code>) <a class="header-anchor" href="#view-a-certificate-crt-pem" aria-label="Permalink to &quot;View a Certificate (\`.crt\` / \`.pem\`)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span></span></code></pre></div><p><em>Look for <code>Issuer:</code> (who signed it), <code>Validity:</code> (when it expires), and <code>Subject Alternative Name:</code> (the domains it covers).</em></p><h3 id="view-a-csr-csr" tabindex="-1">View a CSR (<code>.csr</code>) <a class="header-anchor" href="#view-a-csr-csr" aria-label="Permalink to &quot;View a CSR (\`.csr\`)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> request.csr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span></span></code></pre></div><h3 id="view-a-private-key-key" tabindex="-1">View a Private Key (<code>.key</code>) <a class="header-anchor" href="#view-a-private-key-key" aria-label="Permalink to &quot;View a Private Key (\`.key\`)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -check</span></span></code></pre></div><h3 id="does-the-key-match-the-certificate" tabindex="-1">Does the Key match the Certificate? <a class="header-anchor" href="#does-the-key-match-the-certificate" aria-label="Permalink to &quot;Does the Key match the Certificate?&quot;">​</a></h3><p>If you have a folder full of keys and certs and don&#39;t know which goes with which, you can extract the public modulus from both. If the hashes match, they are a pair!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -modulus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> md5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -modulus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> md5</span></span></code></pre></div><hr><h2 id="_3-format-conversions" tabindex="-1">3. Format Conversions <a class="header-anchor" href="#_3-format-conversions" aria-label="Permalink to &quot;3. Format Conversions&quot;">​</a></h2><p>Different systems require different formats. Nginx/Apache use <strong>PEM</strong> (Base64 text). Windows/IIS and Java often use <strong>PKCS12 / PFX</strong> (Binary).</p><h3 id="pem-to-pkcs12-pfx-p12" tabindex="-1">PEM to PKCS12 (<code>.pfx</code> / <code>.p12</code>) <a class="header-anchor" href="#pem-to-pkcs12-pfx-p12" aria-label="Permalink to &quot;PEM to PKCS12 (\`.pfx\` / \`.p12\`)&quot;">​</a></h3><p>Bundles a private key and a certificate into a single password-protected binary file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pfx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -inkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -certfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ca-chain.crt</span></span></code></pre></div><h3 id="pkcs12-to-pem-extracting-from-pfx" tabindex="-1">PKCS12 to PEM (Extracting from <code>.pfx</code>) <a class="header-anchor" href="#pkcs12-to-pem-extracting-from-pfx" aria-label="Permalink to &quot;PKCS12 to PEM (Extracting from \`.pfx\`)&quot;">​</a></h3><p>If you are migrating off Windows IIS to Linux Nginx, you must extract the text keys from the binary PFX.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract everything (Key + Certs)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pfx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> everything.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nodes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract ONLY the Private Key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pfx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nocerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nodes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract ONLY the Certificates</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pfx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -clcerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nokeys</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span></span></code></pre></div><h3 id="der-binary-to-pem-text" tabindex="-1">DER (Binary) to PEM (Text) <a class="header-anchor" href="#der-binary-to-pem-text" aria-label="Permalink to &quot;DER (Binary) to PEM (Text)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -inform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> der</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.cer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pem</span></span></code></pre></div><hr><h2 id="_4-network-debugging-s-client" tabindex="-1">4. Network Debugging (<code>s_client</code>) <a class="header-anchor" href="#_4-network-debugging-s-client" aria-label="Permalink to &quot;4. Network Debugging (\`s_client\`)&quot;">​</a></h2><p>OpenSSL isn&#39;t just for files; it is a powerful network debugging tool. If a website is throwing an SSL error, you can use <code>s_client</code> to interrogate the remote server&#39;s SSL handshake directly from your terminal.</p><h3 id="check-a-remote-server-s-certificate-chain" tabindex="-1">Check a remote server&#39;s certificate chain <a class="header-anchor" href="#check-a-remote-server-s-certificate-chain" aria-label="Permalink to &quot;Check a remote server&#39;s certificate chain&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -showcerts</span></span></code></pre></div><p><em>This will print out the entire chain of certificates the server is sending. If the intermediate CA is missing, you will see it here.</em></p><h3 id="test-if-a-server-supports-a-specific-tls-version" tabindex="-1">Test if a server supports a specific TLS version <a class="header-anchor" href="#test-if-a-server-supports-a-specific-tls-version" aria-label="Permalink to &quot;Test if a server supports a specific TLS version&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Force TLS 1.2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tls1_2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check if the server still accepts insecure TLS 1.0 (it shouldn&#39;t!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tls1</span></span></code></pre></div><h3 id="check-a-specific-sni-server-name-indication" tabindex="-1">Check a specific SNI (Server Name Indication) <a class="header-anchor" href="#check-a-specific-sni-server-name-indication" aria-label="Permalink to &quot;Check a specific SNI (Server Name Indication)&quot;">​</a></h3><p>If a single IP address hosts multiple websites (like in a Kubernetes Ingress), you MUST specify the <code>-servername</code> flag, otherwise the server won&#39;t know which certificate to serve you.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.0.0.50:443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -servername</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.example.com</span></span></code></pre></div>`,48)])])}const F=i(n,[["render",h]]);export{d as __pageData,F as default};
